/// One child Event row joined to its optional committed `FOP1` bytes.
type SqliteForkSuffixRowV1 = (String, i64, Option<Vec<u8>>);

/// Read every child Event row with its optional `FOP1` after rejecting any
/// orphaned `FOP1`, `EOR1`, or `FIA1`.
///
/// Every query failure inside the snapshot is corrupt authority, as is any
/// row whose columns cannot be read.
fn sqlite_fork_suffix_rows(
    conn: &Connection,
    child_timeline_id: TimelineId,
) -> Result<Vec<SqliteForkSuffixRowV1>, ForkEventAuthorityErrorV1> {
    let child = child_timeline_id.to_string();
    conn.query_row(
        "SELECT EXISTS(SELECT 1 FROM fork_append_operations
         LEFT JOIN events ON events.timeline_id = fork_append_operations.child_id
            AND events.event_id = fork_append_operations.event_id
         WHERE fork_append_operations.child_id = ?1 AND events.event_id IS NULL)",
        params![child],
        |row| row.get::<_, bool>(0),
    )
    .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)
    .and_then(|orphan_operation| {
        sqlite_has_orphaned_fork_provenance(conn, child_timeline_id)
            .map(|orphan_provenance| orphan_operation || orphan_provenance)
    })
    .and_then(|orphaned| {
        if orphaned {
            return Err(ForkEventAuthorityErrorV1::CorruptAuthority);
        }
        conn.prepare(
            "SELECT events.event_id, events.seq, fork_append_operations.fop1_cbor
             FROM events LEFT JOIN fork_append_operations
               ON fork_append_operations.child_id = events.timeline_id
               AND fork_append_operations.event_id = events.event_id
             WHERE events.timeline_id = ?1 ORDER BY events.seq",
        )
        .and_then(|mut statement| {
            statement
                .query_map(params![child], |row| {
                    row.get::<_, String>(0).and_then(|event_id| {
                        row.get::<_, i64>(1).and_then(|local_seq| {
                            row.get::<_, Option<Vec<u8>>>(2)
                                .map(|fop1| (event_id, local_seq, fop1))
                        })
                    })
                })
                .and_then(Iterator::collect::<rusqlite::Result<Vec<_>>>)
        })
        .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)
    })
}

/// Decode one joined suffix row into its Event ID, logical sequence, and `FOP1`.
///
/// A malformed Event ID, an out-of-range sequence, or an absent or
/// noncanonical `FOP1` yields `None`, which the caller reports as corrupt.
fn sqlite_decode_fork_suffix_row(
    prefix: u64,
    row: SqliteForkSuffixRowV1,
) -> Option<(EventId, u64, ForkAppendOperationV1)> {
    let (event_id, local_seq, fop1) = row;
    event_id
        .parse::<ulid::Ulid>()
        .ok()
        .zip(
            u64::try_from(local_seq)
                .ok()
                .and_then(|local_seq| prefix.checked_add(local_seq)),
        )
        .zip(fop1.and_then(|bytes| ForkAppendOperationV1::from_canonical_cbor(&bytes).ok()))
        .map(|((event_id, logical_seq), operation)| {
            (EventId::from_ulid(event_id), logical_seq, operation)
        })
}

/// Detect EOR1/FIA1 rows claiming this child whose Event is absent from it.
///
/// The child is read from each record's fixed canonical offset, so rows that
/// belong to other children, including unrelated corrupt rows, are never decoded.
fn sqlite_has_orphaned_fork_provenance(
    conn: &Connection,
    child_timeline_id: TimelineId,
) -> Result<bool, ForkEventAuthorityErrorV1> {
    conn.query_row(
        "SELECT EXISTS(
             SELECT 1 FROM fork_event_origins
             LEFT JOIN events ON events.timeline_id = ?1
                 AND events.event_id = fork_event_origins.event_id
             WHERE substr(fork_event_origins.eor1_cbor, ?3, 16) = ?2
                 AND events.event_id IS NULL
         ) OR EXISTS(
             SELECT 1 FROM fork_intervention_admissions
             LEFT JOIN events ON events.timeline_id = ?1
                 AND events.event_id = fork_intervention_admissions.event_id
             WHERE substr(fork_intervention_admissions.fia1_cbor, ?4, 16) = ?2
                 AND events.event_id IS NULL
         )",
        params![
            child_timeline_id.to_string(),
            child_timeline_id.inner().to_bytes().as_slice(),
            EOR1_CHILD_TIMELINE_OFFSET,
            FIA1_CHILD_TIMELINE_OFFSET
        ],
        |row| row.get(0),
    )
    .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)
}

const FORK_PUBLICATION_OPERATION_SQL: &str =
    "SELECT fpo1_cbor FROM fork_publication_operations WHERE operation_id = ?1";
const FORK_PUBLICATION_BINDING_SQL: &str = "SELECT fpb1_cbor FROM fork_publication_bindings WHERE child_id = ?1 AND final_logical_head = ?2";
const FORK_PUBLICATION_ARTIFACT_SQL: &str =
    "SELECT fpa1_cbor FROM fork_publication_artifacts WHERE record_id = ?1";
const FORK_PUBLICATION_OPERATION_REFERENCED_SQL: &str = "SELECT EXISTS (SELECT 1 FROM fork_publication_bindings WHERE operation_id = ?1) OR EXISTS (SELECT 1 FROM fork_publication_artifacts WHERE operation_id = ?1)";
const FORK_PUBLICATION_BINDING_OCCUPIED_SQL: &str = "SELECT EXISTS (SELECT 1 FROM fork_publication_bindings WHERE child_id = ?1 AND final_logical_head = ?2)";
const FORK_PUBLICATION_RECORD_PRESENT_SQL: &str = "SELECT EXISTS (SELECT 1 FROM fork_publication_artifacts WHERE record_id = ?1) OR EXISTS (SELECT 1 FROM fork_publication_operations WHERE record_id = ?1) OR EXISTS (SELECT 1 FROM fork_publication_bindings WHERE record_id = ?1)";
const FORK_PUBLICATION_INSERT_OPERATION_SQL: &str = "INSERT INTO fork_publication_operations (operation_id, record_id, fpo1_cbor) VALUES (?1, ?2, ?3)";
const FORK_PUBLICATION_INSERT_BINDING_SQL: &str = "INSERT INTO fork_publication_bindings (child_id, final_logical_head, operation_id, record_id, fpb1_cbor) VALUES (?1, ?2, ?3, ?4, ?5)";
const FORK_PUBLICATION_INSERT_ARTIFACT_SQL: &str = "INSERT INTO fork_publication_artifacts (record_id, operation_id, fpa1_cbor) VALUES (?1, ?2, ?3)";

impl From<rusqlite::Error> for ForkManifestPublicationErrorV1 {
    /// Deliberately conservative: the caller rolls the transaction back, and
    /// no `SQLite` failure is trusted to prove what was or was not committed.
    fn from(_: rusqlite::Error) -> Self {
        Self::StorageIndeterminate
    }
}

/// `SQLite` stores logical heads as signed integers; a head above that range
/// can never have been committed, so a lookup uses an impossible `-1`.
/// Inserts never use this sentinel.
fn sqlite_publication_head(final_logical_head: u64) -> i64 {
    i64::try_from(final_logical_head).unwrap_or(-1)
}

impl SqliteStore {
    /// Read and strictly decode the one stored publication row selected by
    /// `sql`, if any; a noncanonical row is `invalid`.
    fn fork_publication_row<T, E>(
        &self,
        sql: &str,
        params: &[&dyn ToSql],
        decode: fn(&[u8]) -> Result<T, E>,
        invalid: ForkManifestPublicationErrorV1,
    ) -> Result<Option<T>, ForkManifestPublicationErrorV1> {
        self.conn
            .query_row(sql, params, |row| row.get::<_, Vec<u8>>(0))
            .optional()
            .map_err(ForkManifestPublicationErrorV1::from)
            .and_then(|bytes| {
                bytes
                    .map(|bytes| decode(&bytes).ok().ok_or(invalid))
                    .transpose()
            })
    }

    /// Evaluate one publication `EXISTS` predicate.
    fn fork_publication_exists(
        &self,
        sql: &str,
        params: &[&dyn ToSql],
    ) -> Result<bool, ForkManifestPublicationErrorV1> {
        self.conn
            .query_row(sql, params, |row| row.get::<_, bool>(0))
            .map_err(ForkManifestPublicationErrorV1::from)
    }

    /// Read and strictly decode the `FPO1` stored for one operation ID; a
    /// noncanonical row is `invalid`.
    fn fork_publication_operation(
        &self,
        operation_id: Hash,
        invalid: ForkManifestPublicationErrorV1,
    ) -> Result<Option<pos_core::ForkPublicationOperationV1>, ForkManifestPublicationErrorV1> {
        self.fork_publication_row(
            FORK_PUBLICATION_OPERATION_SQL,
            params![operation_id.as_bytes().as_slice()],
            pos_core::ForkPublicationOperationV1::from_canonical_cbor,
            invalid,
        )
    }

    /// Read and strictly decode the `FPB1` stored for one Fork/head key.
    fn fork_publication_binding(
        &self,
        child_timeline_id: TimelineId,
        final_logical_head: u64,
    ) -> Result<Option<pos_core::ForkPublicationBindingV1>, ForkManifestPublicationErrorV1> {
        self.fork_publication_row(
            FORK_PUBLICATION_BINDING_SQL,
            params![
                child_timeline_id.to_string(),
                sqlite_publication_head(final_logical_head)
            ],
            pos_core::ForkPublicationBindingV1::from_canonical_cbor,
            ForkManifestPublicationErrorV1::PublicationConflict,
        )
    }

    /// Read and strictly decode the `FPA1` stored for one record ID.
    fn fork_publication_artifact(
        &self,
        record_id: Hash,
    ) -> Result<Option<pos_core::ForkPublicationArtifactV1>, ForkManifestPublicationErrorV1> {
        self.fork_publication_row(
            FORK_PUBLICATION_ARTIFACT_SQL,
            params![record_id.as_bytes().as_slice()],
            pos_core::ForkPublicationArtifactV1::from_canonical_cbor,
            ForkManifestPublicationErrorV1::PublicationConflict,
        )
    }

    /// Read the admitted Fork's immutable `FAR1` in the open transaction.
    fn fork_publication_admission(
        &self,
        child_timeline_id: TimelineId,
    ) -> PublicationSourceResultV1<ForkAdmissionRecordV1> {
        sqlite_local_fork_admission(&self.conn, self.hasher.as_ref(), child_timeline_id)
            .map_err(PublicationSourceErrorV1::from)
    }

    /// Read the admitted child's classified suffix after its parent cut.
    fn fork_publication_suffix(
        &self,
        child_timeline_id: TimelineId,
        parent_logical_head: PublicationSourceResultV1<u64>,
    ) -> PublicationSourceResultV1<PublicationSuffixV1> {
        parent_logical_head.and_then(|parent_logical_head| {
            self.read_fork_event_suffix_in_transaction(
                child_timeline_id,
                parent_logical_head.saturating_add(1),
            )
            .map_err(PublicationSourceErrorV1::from)
        })
    }

    /// Read the authoritative Fork provenance sources inside the caller's
    /// `BEGIN IMMEDIATE` transaction.
    fn fork_publication_sources(
        &self,
        request: &ForkManifestPublicationRequestV1,
    ) -> Result<PublicationSourcesV1, ForkManifestPublicationErrorV1> {
        let child = request.child_timeline_id;
        let admission = self.fork_publication_admission(child);
        let suffix = self.fork_publication_suffix(child, publication_parent_head(&admission));
        let head_and_chain = Self::logical_head_unchecked_on(&self.conn, child)
            .and_then(|head| {
                Self::compute_chain_hash_at_unchecked_on(
                    &self.conn,
                    self.hasher.as_ref(),
                    child,
                    head,
                )
                .map(|chain| (head.as_u64(), chain))
            })
            .map_err(PublicationSourceErrorV1::from);
        publication_sources(request, admission, head_and_chain, suffix)
    }

    /// Insert all three immutable publication rows in the open transaction.
    fn insert_fork_publication(
        &self,
        graph: &PublicationGraphV1,
    ) -> Result<pos_core::ForkPublicationReceiptV1, ForkManifestPublicationErrorV1> {
        let binding = graph.binding.input();
        let operation_id = binding.operation_id.as_bytes().as_slice();
        let record_id = binding.signed_manifest_record_id.as_bytes().as_slice();
        // The head equals the stored `SQLite` head, so this conversion cannot
        // fail; an impossible head would still be corrupt authority.
        i64::try_from(binding.final_logical_head)
            .ok()
            .ok_or(ForkManifestPublicationErrorV1::CorruptAuthority)
            .and_then(|head| {
                self.conn
                    .execute(
                        FORK_PUBLICATION_INSERT_OPERATION_SQL,
                        params![operation_id, record_id, graph.operation.to_canonical_cbor()],
                    )
                    .and_then(|_| {
                        self.conn.execute(
                            FORK_PUBLICATION_INSERT_BINDING_SQL,
                            params![
                                binding.child_timeline_id.to_string(),
                                head,
                                operation_id,
                                record_id,
                                graph.binding.to_canonical_cbor()
                            ],
                        )
                    })
                    .and_then(|_| {
                        self.conn.execute(
                            FORK_PUBLICATION_INSERT_ARTIFACT_SQL,
                            params![record_id, operation_id, graph.artifact.to_canonical_cbor()],
                        )
                    })
                    .map(|_| graph.receipt)
                    .map_err(ForkManifestPublicationErrorV1::from)
            })
    }

    /// Recover an existing `FPO1` by its full trusted graph read.
    fn recover_fork_publication(
        &self,
        operation: &pos_core::ForkPublicationOperationV1,
        request: &ForkManifestPublicationRequestV1,
    ) -> Result<pos_core::ForkPublicationReceiptV1, ForkManifestPublicationErrorV1> {
        let input = operation.input();
        let committed =
            self.read_committed_fork_publication(input.child_timeline_id, input.final_logical_head);
        recovered_publication_receipt(operation, request, committed)
    }

    /// ADR-099 preflight for an absent `FPO1`: no orphan binding or artifact
    /// may reference the operation, and the Fork/head key must be free.
    fn require_absent_fork_publication(
        &self,
        request: &ForkManifestPublicationRequestV1,
    ) -> Result<(), ForkManifestPublicationErrorV1> {
        self.fork_publication_exists(
            FORK_PUBLICATION_OPERATION_REFERENCED_SQL,
            params![request.operation_id.as_bytes().as_slice()],
        )
        .and_then(|operation_is_referenced| {
            self.fork_publication_exists(
                FORK_PUBLICATION_BINDING_OCCUPIED_SQL,
                params![
                    request.child_timeline_id.to_string(),
                    sqlite_publication_head(request.expected_final_logical_head)
                ],
            )
            .map(|binding_is_occupied| AbsentPublicationPreflightV1 {
                operation_is_referenced,
                binding_is_occupied,
            })
        })
        .and_then(require_absent_publication_graph)
    }

    /// Authorize, read provenance, sign once, reject any orphan `FPO1`,
    /// `FPB1`, or `FPA1` at the new record ID, and insert the graph.
    fn publish_new_fork_publication<E, F>(
        &self,
        request: &ForkManifestPublicationRequestV1,
        sign: F,
    ) -> Result<pos_core::ForkPublicationReceiptV1, ForkManifestPublicationErrorV1>
    where
        F: FnOnce(&HeldRegistryAuthorizationV1, &[u8]) -> Result<Signature, E>,
    {
        self.require_absent_fork_publication(request)
            .and_then(|()| {
                let registry =
                    sqlite_load_key_registry(&self.conn).map_err(PublicationSourceErrorV1::from);
                authorize_publication(request, registry)
            })
            .and_then(|authorization| {
                self.fork_publication_sources(request)
                    .and_then(|sources| sign_publication(request, &authorization, sources, sign))
            })
            .and_then(|graph| {
                let record_id = graph.receipt.signed_manifest_record_id;
                self.fork_publication_exists(
                    FORK_PUBLICATION_RECORD_PRESENT_SQL,
                    params![record_id.as_bytes().as_slice()],
                )
                .and_then(|present| {
                    (!present)
                        .then_some(graph)
                        .ok_or(ForkManifestPublicationErrorV1::CorruptOrConflicting)
                })
            })
            .and_then(|graph| self.insert_fork_publication(&graph))
    }

    /// Recover, reject, or sign and insert inside one `BEGIN IMMEDIATE`.
    fn commit_fork_publication_in_transaction<E, F>(
        &self,
        request: &ForkManifestPublicationRequestV1,
        sign: F,
    ) -> Result<pos_core::ForkPublicationReceiptV1, ForkManifestPublicationErrorV1>
    where
        F: FnOnce(&HeldRegistryAuthorizationV1, &[u8]) -> Result<Signature, E>,
    {
        self.fork_publication_operation(
            request.operation_id,
            ForkManifestPublicationErrorV1::CorruptOrConflicting,
        )
        .and_then(|operation| {
            operation.map_or_else(
                || self.publish_new_fork_publication(request, sign),
                |operation| self.recover_fork_publication(&operation, request),
            )
        })
    }

    /// Join the committed `FPB1`, `FPO1`, and `FPA1` rows for one key.
    fn committed_fork_publication_rows(
        &self,
        child_timeline_id: TimelineId,
        final_logical_head: u64,
    ) -> Result<CommittedPublicationRowsV1, ForkManifestPublicationErrorV1> {
        self.fork_publication_binding(child_timeline_id, final_logical_head)
            .and_then(|binding| binding.ok_or(ForkManifestPublicationErrorV1::PublicationMissing))
            .and_then(|binding| {
                let input = binding.input();
                self.fork_publication_operation(
                    input.operation_id,
                    ForkManifestPublicationErrorV1::PublicationConflict,
                )
                .and_then(|operation| {
                    self.fork_publication_artifact(input.signed_manifest_record_id)
                        .map(|artifact| operation.zip(artifact))
                })
                .and_then(|rows| rows.ok_or(ForkManifestPublicationErrorV1::PublicationConflict))
                .map(|(operation, artifact)| CommittedPublicationRowsV1 {
                    child_timeline_id,
                    final_logical_head,
                    binding,
                    operation,
                    artifact,
                })
            })
    }

    /// Trusted read of one committed graph inside the caller's transaction.
    fn read_committed_fork_publication(
        &self,
        child_timeline_id: TimelineId,
        final_logical_head: u64,
    ) -> Result<crate::CommittedForkManifestV1, ForkManifestPublicationErrorV1> {
        self.committed_fork_publication_rows(child_timeline_id, final_logical_head)
            .and_then(|rows| {
                let admission = self.fork_publication_admission(child_timeline_id);
                let suffix = self.fork_publication_suffix(
                    child_timeline_id,
                    publication_parent_head(&admission),
                );
                let final_chain_head_hash = Self::compute_chain_hash_at_unchecked_on(
                    &self.conn,
                    self.hasher.as_ref(),
                    child_timeline_id,
                    Seq::from_u64(final_logical_head),
                )
                .map_err(PublicationSourceErrorV1::from);
                let registry =
                    sqlite_load_key_registry(&self.conn).map_err(PublicationSourceErrorV1::from);
                let sources = CommittedPublicationSourcesV1 {
                    admission,
                    final_chain_head_hash,
                    suffix,
                    registry,
                };
                trusted_committed_manifest(&rows, sources)
            })
    }
}

impl ForkManifestPublicationPortV1 for SqliteStore {
    fn commit_authorized<E, F>(
        &mut self,
        request: ForkManifestPublicationRequestV1,
        sign: F,
    ) -> Result<pos_core::ForkPublicationReceiptV1, ForkManifestPublicationErrorV1>
    where
        F: FnOnce(&HeldRegistryAuthorizationV1, &[u8]) -> Result<Signature, E>,
    {
        // The rusqlite transaction guard rolls back on every early exit,
        // including an unwinding signer, so no write lock outlives the call.
        validate_publication_request(&request).and_then(|()| {
            rusqlite::Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)
                .map_err(ForkManifestPublicationErrorV1::from)
                .and_then(|transaction| {
                    let result = self.commit_fork_publication_in_transaction(&request, sign);
                    finish_fork_publication_transaction(transaction, result)
                })
        })
    }

    fn read_committed(
        &self,
        child_timeline_id: TimelineId,
        final_logical_head: u64,
    ) -> Result<crate::CommittedForkManifestV1, ForkManifestPublicationErrorV1> {
        rusqlite::Transaction::new_unchecked(&self.conn, TransactionBehavior::Deferred)
            .map_err(ForkManifestPublicationErrorV1::from)
            .and_then(|transaction| {
                let result =
                    self.read_committed_fork_publication(child_timeline_id, final_logical_head);
                finish_fork_publication_transaction(transaction, result)
            })
    }
}

/// Commit a successful publication step, or roll back a failed one; an
/// unknown commit or rollback outcome is `StorageIndeterminate`.
fn finish_fork_publication_transaction<T>(
    transaction: rusqlite::Transaction<'_>,
    result: Result<T, ForkManifestPublicationErrorV1>,
) -> Result<T, ForkManifestPublicationErrorV1> {
    match result {
        Ok(value) => transaction
            .commit()
            .map(|()| value)
            .map_err(ForkManifestPublicationErrorV1::from),
        Err(error) => Err(transaction
            .rollback()
            .map_or(ForkManifestPublicationErrorV1::StorageIndeterminate, |()| {
                error
            })),
    }
}

fn sqlite_local_fork_admission(
    conn: &Connection,
    hasher: &dyn Hasher,
    child_timeline_id: TimelineId,
) -> Result<ForkAdmissionRecordV1, ForkEventAuthorityErrorV1> {
    conn.query_row(
        "SELECT far1_cbor FROM fork_admissions WHERE child_id = ?1",
        params![child_timeline_id.to_string()],
        |row| row.get::<_, Vec<u8>>(0),
    )
    .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)
    .and_then(|bytes| {
        ForkAdmissionRecordV1::from_canonical_cbor(&bytes)
            .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)
    })
    .and_then(|admission| {
        (admission.input().child_timeline_id == child_timeline_id
            && admission.input().origin == ForkAttributionOriginV1::Local)
            .then_some(admission)
            .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)
    })
    .and_then(|admission| {
        // A missing or unreadable FCC1 row and a receipt naming another FAR1
        // are all corrupt authority.
        let expected = ForkAdmissionOperationResultV1::Fork(ForkAdmissionReceiptV1 {
            child_id: child_timeline_id,
            admission_digest: admission.digest(),
        });
        sqlite_fork_admission_operation(
            conn,
            ForkAdmissionOperationKindV1::Fork,
            admission.input().operation_id,
        )
        .ok()
        .flatten()
        .and_then(|row| sqlite_fork_admission_result(conn, hasher, &row).ok())
        .filter(|result| *result == expected)
        .map(|_| admission)
        .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)
    })
}

fn sqlite_classified_event(
    conn: &Connection,
    operation: &ForkAppendOperationV1,
) -> Result<Event, ForkEventAuthorityErrorV1> {
    let child_timeline_id = operation.input().child_timeline_id;
    let logical_seq = operation.input().logical_seq;
    // Any unreadable prefix or Event row, and any Event not exactly bound to
    // this FOP1, is corrupt authority.
    read_origin_prefix(conn, child_timeline_id)
        .ok()
        .and_then(|prefix| {
            logical_seq.checked_sub(prefix).and_then(|local_seq| {
                SqliteStore::read_own_events_limited_on(
                    conn,
                    child_timeline_id,
                    Seq::from_u64(local_seq),
                    Some(Seq::from_u64(local_seq)),
                    Some(1),
                    None,
                    u64::MAX,
                )
                .ok()
                .and_then(|mut events| events.pop())
                .and_then(|event| SqliteStore::logical_event(prefix, event).ok())
            })
        })
        .filter(|event| {
            event.id == operation.input().event_id
                && event.seq.as_u64() == logical_seq
                && event.origin.is_some_and(|origin| {
                    origin.origin_timeline_id == child_timeline_id
                        && origin.origin_logical_seq.as_u64() == logical_seq
                })
        })
        .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)
}

/// Read the committed Event for one FOP1 and revalidate its full provenance.
fn sqlite_validated_classified_event(
    conn: &Connection,
    hasher: &dyn Hasher,
    operation: &ForkAppendOperationV1,
) -> Result<Event, ForkEventAuthorityErrorV1> {
    sqlite_classified_event(conn, operation).and_then(|event| {
        sqlite_validate_classified_provenance(conn, hasher, operation).map(|()| event)
    })
}

fn sqlite_validate_classified_permit(
    conn: &Connection,
    hasher: &dyn Hasher,
    permit: &ForkAppendSourcePermitV1,
) -> Result<ForkClassifierTableV1, ForkEventAuthorityErrorV1> {
    sqlite_classified_authority_graph(conn, hasher, permit.child_timeline_id()).and_then(
        |(admission, table, registration)| {
            permit
                .names_scope(&admission, &table, &registration)
                .then_some(table)
                .ok_or(ForkEventAuthorityErrorV1::Unauthenticated)
        },
    )
}

fn persist_classified_append(
    conn: &Connection,
    local_seq: Seq,
    provenance: &ForkClassifiedProvenanceV1,
) -> Result<(), ForkEventAuthorityErrorV1> {
    let operation = provenance.operation.input();
    let event_id = operation.event_id.to_string();
    conn.execute(
        "INSERT INTO fork_event_origins (event_id, eor1_cbor)
         VALUES (?1, ?2)",
        params![event_id, provenance.origin.to_canonical_cbor()],
    )
    .and_then(|_| {
        provenance
            .intervention
            .as_ref()
            .map_or(Ok(0), |intervention| {
                conn.execute(
                    "INSERT INTO fork_intervention_admissions (event_id, fia1_cbor)
                     VALUES (?1, ?2)",
                    params![event_id, intervention.to_canonical_cbor()],
                )
            })
    })
    .map_err(|_| ForkEventAuthorityErrorV1::StorageIndeterminate)
    .and_then(|_| {
        conn.execute(
            "INSERT INTO fork_append_operations
             (operation_id, child_id, local_seq, event_id, fop1_cbor)
             VALUES (?1, ?2, ?3, ?4, ?5)",
            params![
                operation.operation_id.as_bytes().as_slice(),
                operation.child_timeline_id.to_string(),
                seq_as_i64(local_seq),
                event_id,
                provenance.operation.to_canonical_cbor(),
            ],
        )
        .map(|_| ())
        .map_err(|error| fork_event_insert_error(&error))
    })
}

/// Map an INSERT failure: only a `SQLite` constraint rejection is a `Conflict`.
fn fork_event_insert_error(error: &rusqlite::Error) -> ForkEventAuthorityErrorV1 {
    if error.sqlite_error_code() == Some(rusqlite::ErrorCode::ConstraintViolation) {
        ForkEventAuthorityErrorV1::Conflict
    } else {
        ForkEventAuthorityErrorV1::StorageIndeterminate
    }
}

fn sqlite_validate_classified_provenance(
    conn: &Connection,
    hasher: &dyn Hasher,
    operation: &ForkAppendOperationV1,
) -> Result<(), ForkEventAuthorityErrorV1> {
    let input = operation.input();
    sqlite_validate_classified_authority_graph(
        conn,
        hasher,
        input.child_timeline_id,
        input.fork_admission_digest,
        input.classifier_revision_digest,
    )
    .and_then(|(_, table)| sqlite_validate_classified_records(conn, operation, &table))
    .map(|_| ())
}

/// Require the committed Event, EOR1, and FIA1 exactly bound by one FOP1.
fn sqlite_validate_classified_records(
    conn: &Connection,
    operation: &ForkAppendOperationV1,
    table: &ForkClassifierTableV1,
) -> Result<(EventOriginRecordV1, Option<ForkInterventionAdmissionV1>), ForkEventAuthorityErrorV1> {
    let input = operation.input();
    sqlite_classified_event(conn, operation)
        .and_then(|event| {
            sqlite_event_origin(conn, input.event_id)
                .and_then(|origin| {
                    sqlite_intervention_admission(conn, input.event_id)
                        .map(|intervention| (event, origin, intervention))
                })
                .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)
        })
        .and_then(|(event, origin, intervention)| {
            // An unclassifiable FOP1 source is corrupt authority, exactly like
            // any record that differs from its expected provenance.
            ForkEventClassifierV1::from_table(table)
                .classify_identity(&input.source)
                .ok()
                .filter(|classification| {
                    let (expected_origin, expected_intervention) =
                        operation.expected_provenance(table, *classification);
                    event.payload_hash == input.payload_hash
                        && origin == expected_origin
                        && origin.digest() == input.event_origin_digest
                        && intervention == expected_intervention
                        && intervention
                            .as_ref()
                            .map(ForkInterventionAdmissionV1::digest)
                            == input.intervention_admission_digest
                })
                .map(|_| (origin, intervention))
                .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)
        })
}

/// Rebuild the complete immutable ADR-099 authority graph for one child.
///
/// `FOP1` digests are evidence, never a substitute for rereading the local
/// FAR1/FCS1/FCT1/FCR1 authority closure.
fn sqlite_classified_authority_graph(
    conn: &Connection,
    hasher: &dyn Hasher,
    child_id: TimelineId,
) -> Result<
    (
        ForkAdmissionRecordV1,
        ForkClassifierTableV1,
        ForkClassifierRegistrationV1,
    ),
    ForkEventAuthorityErrorV1,
> {
    let admission = sqlite_local_fork_admission(conn, hasher, child_id)?;
    let table = sqlite_fork_classifier_table(conn, child_id)
        .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)?
        .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)?;
    let registration_bytes = conn
        .query_row(
            "SELECT fcr1_cbor FROM fork_classifier_registrations WHERE child_id = ?1",
            params![child_id.to_string()],
            |row| row.get::<_, Vec<u8>>(0),
        )
        .optional()
        .ok()
        .flatten()
        .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)?;
    let registration = ForkClassifierRegistrationV1::from_canonical_cbor(&registration_bytes)
        .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)?;
    let source = sqlite_fork_classifier_source(
        conn,
        table.input().room_revision_descriptor_hash,
        &table.input().registrar_identifier,
    )
    .map_err(|_| ForkEventAuthorityErrorV1::CorruptAuthority)?
    .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)?;
    (table.input().fork_admission_digest == admission.digest()
        && table.input().room_revision_descriptor_hash
            == admission.input().room_revision_descriptor_hash
        && source.input().room_revision_descriptor_hash
            == table.input().room_revision_descriptor_hash
        && source.input().registrar_identifier == table.input().registrar_identifier
        && table.input().source_configuration_revision_digest == source.digest()
        && table.input().routes == source.input().routes
        && registration.input().child_timeline_id == child_id
        && registration.input().fork_admission_digest == admission.digest()
        && registration.input().room_revision_descriptor_hash
            == admission.input().room_revision_descriptor_hash
        && registration.input().classifier_revision_digest == table.digest())
    .then_some((admission, table, registration))
    .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)
}

/// Validate the child's authority closure against digests retained by evidence.
fn sqlite_validate_classified_authority_graph(
    conn: &Connection,
    hasher: &dyn Hasher,
    child_id: TimelineId,
    fork_admission_digest: Hash,
    classifier_revision_digest: Hash,
) -> Result<(ForkAdmissionRecordV1, ForkClassifierTableV1), ForkEventAuthorityErrorV1> {
    sqlite_classified_authority_graph(conn, hasher, child_id).and_then(|(admission, table, _)| {
        (admission.digest() == fork_admission_digest
            && table.digest() == classifier_revision_digest)
            .then_some((admission, table))
            .ok_or(ForkEventAuthorityErrorV1::CorruptAuthority)
    })
}

fn finish_fork_event_transaction<T>(
    conn: &Connection,
    result: Result<T, ForkEventAuthorityErrorV1>,
) -> Result<T, ForkEventAuthorityErrorV1> {
    match result {
        Ok(value) => conn
            .execute_batch("COMMIT")
            .map(|()| value)
            .map_err(|_| ForkEventAuthorityErrorV1::StorageIndeterminate),
        Err(error) => conn
            .execute_batch("ROLLBACK")
            .map(|()| error)
            .map_or(Err(ForkEventAuthorityErrorV1::StorageIndeterminate), Err),
    }
}

/// Allocates the next never-reused owner fence, refusing a missing,
/// exhausted, negative, or lagging counter.
const FORK_DELIVERY_ALLOCATE_FENCE_SQL: &str = "UPDATE fork_delivery_fence_counter SET last_fence = last_fence + 1 WHERE id = 1 AND last_fence < 9223372036854775807 AND last_fence >= COALESCE((SELECT MAX(owner_fence) FROM fork_delivery_journal), 0)";
const FORK_DELIVERY_READ_FENCE_SQL: &str =
    "SELECT last_fence FROM fork_delivery_fence_counter WHERE id = 1";
const FORK_DELIVERY_INSERT_SQL: &str = "INSERT INTO fork_delivery_journal (host_request_id, kind, operation_id, state, owner_fence) VALUES (?1, ?2, ?3, ?4, ?5)";
/// Deletes one exact fenced row in state `?5`.
const FORK_DELIVERY_DELETE_OWNED_SQL: &str = "DELETE FROM fork_delivery_journal WHERE host_request_id = ?1 AND kind = ?2 AND operation_id = ?3 AND owner_fence = ?4 AND state = ?5";
/// Deletes one exact row in state `?4` regardless of owner.
const FORK_DELIVERY_DELETE_DELIVERED_SQL: &str = "DELETE FROM fork_delivery_journal WHERE host_request_id = ?1 AND kind = ?2 AND operation_id = ?3 AND state = ?4";
/// Moves one exact fenced row from state `?6` or `?7` to state `?1`.
const FORK_DELIVERY_SET_STATE_SQL: &str = "UPDATE fork_delivery_journal SET state = ?1 WHERE host_request_id = ?2 AND kind = ?3 AND operation_id = ?4 AND owner_fence = ?5 AND state IN (?6, ?7)";

/// Validates the live session against durable FAH1 and returns that host.
/// An unreadable authority state and a stale session are both `Corrupt`.
fn sqlite_validate_delivery_session(
    store: &SqliteStore,
    session: &ForkAdmissionAuthoritySessionV1,
) -> Result<ForkAdmissionHostRecordV1, ForkDeliveryJournalErrorV1> {
    read_fork_admission_authority_state(&store.conn)
        .ok()
        .and_then(|mut state| {
            state.session_identity = store.fork_admission_authority_runtime.session_identity;
            state
                .host
                .filter(|_| validate_live_session(&state, session))
        })
        .ok_or(ForkDeliveryJournalErrorV1::Corrupt)
}

/// One retained journal row as stored: request, kind, operation, state, fence.
type SqliteForkDeliveryScanRowV1 = (Vec<u8>, i64, Vec<u8>, i64, i64);

/// Reads every journal row with typed columns; any prepare, step, or column
/// type failure is one `rusqlite` error for the caller to map.
fn sqlite_fork_delivery_scan(
    conn: &Connection,
) -> rusqlite::Result<Vec<SqliteForkDeliveryScanRowV1>> {
    conn.prepare(
        "SELECT host_request_id, kind, operation_id, state, owner_fence FROM fork_delivery_journal",
    )
    .and_then(|mut statement| {
        let rows = statement
            .query_map([], |row| SqliteForkDeliveryScanRowV1::try_from(row))
            .and_then(Iterator::collect);
        rows
    })
}

fn finish_fork_delivery_transaction<T>(
    conn: &Connection,
    result: Result<T, ForkDeliveryJournalErrorV1>,
) -> Result<T, ForkDeliveryJournalErrorV1> {
    match result {
        Ok(value) => conn
            .execute_batch("COMMIT")
            .map(|()| value)
            .map_err(|_| ForkDeliveryJournalErrorV1::StorageIndeterminate),
        Err(error) => Err(conn
            .execute_batch("ROLLBACK")
            .map_or(ForkDeliveryJournalErrorV1::StorageIndeterminate, |()| error)),
    }
}

/// Rolls back a failed FAC1 transaction, then records Uncertain in a fresh one.
fn sqlite_record_uncertain_after_rollback(
    conn: &Connection,
    tuple: ForkDeliveryTupleV1,
    owner_fence: i64,
) -> Result<ForkDeliveryExecutionV1, ForkDeliveryJournalErrorV1> {
    conn.execute_batch("ROLLBACK")
        .and_then(|()| conn.execute_batch("BEGIN IMMEDIATE"))
        .map_err(|_| ForkDeliveryJournalErrorV1::StorageIndeterminate)
        .and_then(|()| {
            let state = sqlite_set_fork_delivery_state(
                conn,
                tuple,
                owner_fence,
                ForkDeliveryStateV1::Uncertain,
                ForkDeliveryStateV1::Pending,
            );
            finish_fork_delivery_transaction(conn, state)
        })
        .map(|()| ForkDeliveryExecutionV1::Uncertain)
}

/// Opens the savepoint that scopes one permit-bearing FAC1 inside its
/// delivery transaction (ADR-109 revision 9, Decision 2 step 5).
const SQLITE_FAC1_SAVEPOINT_SQL: &str = "SAVEPOINT fork_delivery_fac1";
/// Rolls back only the FAC1 portion of a delivery transaction.
const SQLITE_FAC1_ROLLBACK_TO_SQL: &str = "ROLLBACK TO fork_delivery_fac1";

/// Rolls back a permit-bearing delivery transaction through its erasure
/// context, then records Uncertain in a fresh journal-only transaction.
fn sqlite_record_uncertain_after_permit_rollback(
    context: &pos_core::ErasureAdmittedForkContextV1<'_>,
    conn: &Connection,
    tuple: ForkDeliveryTupleV1,
    owner_fence: i64,
) -> Result<ForkDeliveryExecutionV1, ForkDeliveryJournalErrorV1> {
    context
        .roll_back_write_boundary(|| conn.execute_batch("ROLLBACK"))
        .and_then(|()| conn.execute_batch("BEGIN IMMEDIATE"))
        .ok()
        .ok_or(ForkDeliveryJournalErrorV1::StorageIndeterminate)
        .and_then(|()| {
            let state = sqlite_set_fork_delivery_state(
                conn,
                tuple,
                owner_fence,
                ForkDeliveryStateV1::Uncertain,
                ForkDeliveryStateV1::Pending,
            );
            finish_fork_delivery_transaction(conn, state)
        })
        .map(|()| ForkDeliveryExecutionV1::Uncertain)
}

fn sqlite_fork_delivery_tuple(
    host_request_id: Vec<u8>,
    kind: i64,
    operation_id: Vec<u8>,
) -> Result<ForkDeliveryTupleV1, ForkDeliveryJournalErrorV1> {
    let kind = [
        ForkAdmissionOperationKindV1::PrincipalOwner,
        ForkAdmissionOperationKindV1::Fork,
    ]
    .into_iter()
    .find(|candidate| i64::from(candidate.wire()) == kind)
    .ok_or(ForkDeliveryJournalErrorV1::Corrupt)?;
    let host_request_id =
        sqlite_hash(host_request_id).map_err(|_| ForkDeliveryJournalErrorV1::Corrupt)?;
    let operation_id =
        sqlite_hash(operation_id).map_err(|_| ForkDeliveryJournalErrorV1::Corrupt)?;
    ForkDeliveryTupleV1::new(host_request_id, kind, operation_id)
        .map_err(|_| ForkDeliveryJournalErrorV1::Corrupt)
}

fn sqlite_decode_fork_delivery_row(
    host_request_id: Vec<u8>,
    kind: i64,
    operation_id: Vec<u8>,
    state: i64,
    owner_fence: i64,
) -> Result<ForkDeliveryRowV1, ForkDeliveryJournalErrorV1> {
    let tuple = sqlite_fork_delivery_tuple(host_request_id, kind, operation_id)?;
    let state = u8::try_from(state)
        .ok()
        .and_then(ForkDeliveryStateV1::from_wire)
        .ok_or(ForkDeliveryJournalErrorV1::Corrupt)?;
    let owner_fence =
        u64::try_from(owner_fence).map_err(|_| ForkDeliveryJournalErrorV1::Corrupt)?;
    if owner_fence == 0 {
        return Err(ForkDeliveryJournalErrorV1::Corrupt);
    }
    Ok(ForkDeliveryRowV1 {
        tuple,
        state,
        owner_fence,
    })
}

fn sqlite_fork_delivery_row(
    conn: &Connection,
    host_request_id: Hash,
) -> Result<Option<ForkDeliveryRowV1>, ForkDeliveryJournalErrorV1> {
    conn.query_row(
        "SELECT kind, operation_id, state, owner_fence FROM fork_delivery_journal WHERE host_request_id = ?1",
        params![host_request_id.as_bytes().as_slice()],
        |row| <(i64, Vec<u8>, i64, i64)>::try_from(row),
    )
    .optional()
    .map_err(|_| ForkDeliveryJournalErrorV1::StorageIndeterminate)
    .and_then(|row| {
        row.map_or(Ok(None), |(kind, operation_id, state, owner_fence)| {
            sqlite_decode_fork_delivery_row(
                host_request_id.as_bytes().to_vec(),
                kind,
                operation_id,
                state,
                owner_fence,
            )
            .map(Some)
        })
    })
}

fn sqlite_fork_delivery_fence_counter(
    conn: &Connection,
) -> Result<i64, ForkDeliveryJournalErrorV1> {
    conn.query_row(FORK_DELIVERY_READ_FENCE_SQL, [], |row| row.get::<_, i64>(0))
        .map_err(|_| ForkDeliveryJournalErrorV1::StorageIndeterminate)
}

/// Inserts a fresh Pending row. Only a UNIQUE/PRIMARY KEY violation is a
/// tuple conflict; every other failure is an indeterminate write.
fn sqlite_insert_pending_fork_delivery(
    conn: &Connection,
    tuple: ForkDeliveryTupleV1,
    owner_fence: i64,
) -> Result<(), ForkDeliveryJournalErrorV1> {
    conn.execute(
        FORK_DELIVERY_INSERT_SQL,
        params![
            tuple.host_request_id.as_bytes().as_slice(),
            i64::from(tuple.kind.wire()),
            tuple.operation_id.as_bytes().as_slice(),
            i64::from(ForkDeliveryStateV1::Pending.to_wire()),
            owner_fence,
        ],
    )
    .map(|_| ())
    .map_err(|error| {
        if matches!(
            error.sqlite_error().map(|failure| failure.extended_code),
            Some(
                rusqlite::ffi::SQLITE_CONSTRAINT_UNIQUE
                    | rusqlite::ffi::SQLITE_CONSTRAINT_PRIMARYKEY
            )
        ) {
            ForkDeliveryJournalErrorV1::Conflict
        } else {
            ForkDeliveryJournalErrorV1::StorageIndeterminate
        }
    })
}

fn sqlite_delete_pending_fork_delivery(
    conn: &Connection,
    tuple: ForkDeliveryTupleV1,
    owner_fence: i64,
) -> Result<usize, ForkDeliveryJournalErrorV1> {
    conn.execute(
        FORK_DELIVERY_DELETE_OWNED_SQL,
        params![
            tuple.host_request_id.as_bytes().as_slice(),
            i64::from(tuple.kind.wire()),
            tuple.operation_id.as_bytes().as_slice(),
            owner_fence,
            i64::from(ForkDeliveryStateV1::Pending.to_wire()),
        ],
    )
    .map_err(|_| ForkDeliveryJournalErrorV1::StorageIndeterminate)
}

fn sqlite_owner_fence(owner_fence: u64) -> Result<i64, ForkDeliveryJournalErrorV1> {
    i64::try_from(owner_fence).map_err(|_| ForkDeliveryJournalErrorV1::Fenced)
}

/// Moves an exact fenced row to `state` from Uncertain or `also_from`.
fn sqlite_set_fork_delivery_state(
    conn: &Connection,
    tuple: ForkDeliveryTupleV1,
    owner_fence: i64,
    state: ForkDeliveryStateV1,
    also_from: ForkDeliveryStateV1,
) -> Result<(), ForkDeliveryJournalErrorV1> {
    let affected = conn
        .execute(
            FORK_DELIVERY_SET_STATE_SQL,
            params![
                i64::from(state.to_wire()),
                tuple.host_request_id.as_bytes().as_slice(),
                i64::from(tuple.kind.wire()),
                tuple.operation_id.as_bytes().as_slice(),
                owner_fence,
                i64::from(ForkDeliveryStateV1::Uncertain.to_wire()),
                i64::from(also_from.to_wire()),
            ],
        )
        .map_err(|_| ForkDeliveryJournalErrorV1::StorageIndeterminate)?;
    if affected == 1 {
        Ok(())
    } else {
        Err(ForkDeliveryJournalErrorV1::Fenced)
    }
}

fn sqlite_delivery_result_matches_principal(
    conn: &Connection,
    hasher: &dyn Hasher,
    result: &ForkAdmissionOperationResultV1,
    principal_digest: Hash,
) -> bool {
    match result {
        ForkAdmissionOperationResultV1::PrincipalOwner(binding) => {
            binding.input().principal_digest == principal_digest
        }
        ForkAdmissionOperationResultV1::Fork(receipt) => {
            sqlite_local_fork_admission(conn, hasher, receipt.child_id)
                .ok()
                .and_then(|admission| {
                    sqlite_fork_principal_owner_binding(
                        conn,
                        admission.input().principal_owner_binding_digest,
                    )
                    .ok()
                })
                .is_some_and(|binding| binding.input().principal_digest == principal_digest)
        }
    }
}

fn sqlite_fork_admission_operation(
    conn: &Connection,
    kind: ForkAdmissionOperationKindV1,
    operation_id: Hash,
) -> Result<Option<ForkAdmissionOperationRowV1>, pos_core::ForkAdmissionErrorV1> {
    conn.query_row(
        "SELECT evidence_digest, commitment, result_digest, child_id
         FROM fork_admission_operations
         WHERE kind = ?1 AND operation_id = ?2",
        params![i64::from(kind.wire()), operation_id.as_bytes().as_slice()],
        |row| {
            Ok((
                row.get::<_, Vec<u8>>(0)?,
                row.get::<_, Vec<u8>>(1)?,
                row.get::<_, Vec<u8>>(2)?,
                row.get::<_, Option<String>>(3)?,
            ))
        },
    )
    .optional()
    .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)
    .and_then(|record| {
        record.map_or(
            Ok(None),
            |(evidence_digest, commitment, result_digest, child_id)| {
                child_id
                    .map(|id| {
                        id.parse::<ulid::Ulid>()
                            .map(TimelineId::from_ulid)
                            .map_err(|_| pos_core::ForkAdmissionErrorV1::CorruptAuthority)
                    })
                    .transpose()
                    .and_then(|child_id| {
                        Ok(Some(ForkAdmissionOperationRowV1 {
                            kind,
                            operation_id,
                            evidence_digest: sqlite_hash(evidence_digest)?,
                            commitment: sqlite_hash(commitment)?,
                            result_digest: sqlite_hash(result_digest)?,
                            child_id,
                        }))
                    })
            },
        )
    })
}

fn sqlite_insert_fork_admission_operation(
    conn: &Connection,
    row: &ForkAdmissionOperationRowV1,
) -> Result<(), pos_core::ForkAdmissionErrorV1> {
    conn.execute(
        "INSERT INTO fork_admission_operations
         (kind, operation_id, evidence_digest, commitment, result_digest, child_id)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            i64::from(row.kind.wire()),
            row.operation_id.as_bytes().as_slice(),
            row.evidence_digest.as_bytes().as_slice(),
            row.commitment.as_bytes().as_slice(),
            row.result_digest.as_bytes().as_slice(),
            row.child_id.map(|id| id.to_string()),
        ],
    )
    .map(|_| ())
    .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)
}

fn sqlite_principal_owner_binding(
    conn: &Connection,
    principal_digest: Hash,
) -> Result<Option<PrincipalOwnerBindingV1>, pos_core::ForkAdmissionErrorV1> {
    // The key column equals the queried digest, so only the other columns
    // are read back from durable state.
    conn.query_row(
        "SELECT operation_id, pob1_cbor
         FROM fork_principal_owner_bindings
         WHERE principal_digest = ?1",
        params![principal_digest.as_bytes().as_slice()],
        |row| {
            Ok((
                row.get::<_, Vec<u8>>(0)?,
                principal_digest.as_bytes().to_vec(),
                row.get::<_, Vec<u8>>(1)?,
            ))
        },
    )
    .optional()
    .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)
    .and_then(|bytes| bytes.map(sqlite_decode_principal_owner_binding).transpose())
}

fn sqlite_fork_admission_result(
    conn: &Connection,
    hasher: &dyn Hasher,
    row: &ForkAdmissionOperationRowV1,
) -> Result<ForkAdmissionOperationResultV1, pos_core::ForkAdmissionErrorV1> {
    let store_id = sqlite_fork_admission_store_id(conn)?;
    match (row.kind, row.child_id) {
        (ForkAdmissionOperationKindV1::PrincipalOwner, None) => {
            sqlite_principal_owner_result(conn, store_id, row)
                .map(ForkAdmissionOperationResultV1::PrincipalOwner)
        }
        (ForkAdmissionOperationKindV1::Fork, Some(child_id)) => {
            let bytes = conn
                .query_row(
                    "SELECT far1_cbor FROM fork_admissions WHERE child_id = ?1",
                    params![child_id.to_string()],
                    |record| record.get::<_, Vec<u8>>(0),
                )
                .optional()
                .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)?
                .ok_or(pos_core::ForkAdmissionErrorV1::CorruptAuthority)?;
            let admission = ForkAdmissionRecordV1::from_canonical_cbor(&bytes)
                .map_err(|_| pos_core::ForkAdmissionErrorV1::CorruptAuthority)?;
            if admission.digest() != row.result_digest
                || admission.input().operation_id != row.operation_id
                || admission.input().child_timeline_id != child_id
            {
                return Err(pos_core::ForkAdmissionErrorV1::CorruptAuthority);
            }
            let binding = sqlite_fork_principal_owner_binding(
                conn,
                admission.input().principal_owner_binding_digest,
            )?;
            if binding.input().owner != admission.input().creator {
                return Err(pos_core::ForkAdmissionErrorV1::CorruptAuthority);
            }
            let parent_chain_head = SqliteStore::compute_chain_hash_at_unchecked_on(
                conn,
                hasher,
                admission.input().parent_timeline_id,
                Seq::from_u64(admission.input().parent_logical_head),
            )
            .map_err(|_| pos_core::ForkAdmissionErrorV1::CorruptAuthority)?;
            if parent_chain_head != admission.input().parent_chain_head_hash {
                return Err(pos_core::ForkAdmissionErrorV1::CorruptAuthority);
            }
            let child_name = sqlite_fork_admission_child_name(conn, &admission)?
                .ok_or(pos_core::ForkAdmissionErrorV1::CorruptAuthority)?;
            if fork_commitment(
                store_id,
                binding.input().principal_digest,
                row.evidence_digest,
                &admission,
                &child_name,
            ) != row.commitment
            {
                return Err(pos_core::ForkAdmissionErrorV1::CorruptAuthority);
            }
            Ok(ForkAdmissionOperationResultV1::Fork(
                ForkAdmissionReceiptV1 {
                    child_id,
                    admission_digest: row.result_digest,
                },
            ))
        }
        _ => Err(pos_core::ForkAdmissionErrorV1::CorruptAuthority),
    }
}

/// Validate one POB1 operation row against its keyed binding and the
/// reconstructed commitment.
fn sqlite_principal_owner_result(
    conn: &Connection,
    store_id: Hash,
    row: &ForkAdmissionOperationRowV1,
) -> Result<PrincipalOwnerBindingV1, pos_core::ForkAdmissionErrorV1> {
    // The key column equals the row's operation ID, so only the other
    // columns are read back from durable state.
    let binding = conn
        .query_row(
            "SELECT principal_digest, pob1_cbor
             FROM fork_principal_owner_bindings
             WHERE operation_id = ?1",
            params![row.operation_id.as_bytes().as_slice()],
            |record| {
                Ok((
                    row.operation_id.as_bytes().to_vec(),
                    record.get::<_, Vec<u8>>(0)?,
                    record.get::<_, Vec<u8>>(1)?,
                ))
            },
        )
        .optional()
        .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)?
        .ok_or(pos_core::ForkAdmissionErrorV1::CorruptAuthority)
        .and_then(sqlite_decode_principal_owner_binding)?;
    if binding.digest() != row.result_digest
        || principal_owner_commitment(store_id, &binding, row.evidence_digest) != row.commitment
    {
        return Err(pos_core::ForkAdmissionErrorV1::CorruptAuthority);
    }
    Ok(binding)
}

/// Resolve the POB1 behind a FAR1 through its committed POB1 operation row.
///
/// The lookup is keyed by that row's result digest and the binding's
/// operation ID, so an unrelated corrupt binding cannot fail it. A binding
/// without its exact operation row is orphaned, corrupt authority.
fn sqlite_fork_principal_owner_binding(
    conn: &Connection,
    binding_digest: Hash,
) -> Result<PrincipalOwnerBindingV1, pos_core::ForkAdmissionErrorV1> {
    conn.query_row(
        "SELECT operation_id FROM fork_admission_operations
         WHERE kind = 1 AND result_digest = ?1",
        params![binding_digest.as_bytes().as_slice()],
        |record| record.get::<_, Vec<u8>>(0),
    )
    .optional()
    .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)
    .and_then(|operation_id| operation_id.ok_or(pos_core::ForkAdmissionErrorV1::CorruptAuthority))
    .and_then(sqlite_hash)
    .and_then(|operation_id| {
        sqlite_fork_admission_operation(
            conn,
            ForkAdmissionOperationKindV1::PrincipalOwner,
            operation_id,
        )
    })
    .and_then(|binding_row| {
        binding_row
            .filter(|binding_row| binding_row.child_id.is_none())
            .ok_or(pos_core::ForkAdmissionErrorV1::CorruptAuthority)
    })
    .and_then(|binding_row| {
        sqlite_fork_admission_store_id(conn)
            .and_then(|store_id| sqlite_principal_owner_result(conn, store_id, &binding_row))
    })
}

fn sqlite_fork_admission_store_id(
    conn: &Connection,
) -> Result<Hash, pos_core::ForkAdmissionErrorV1> {
    read_fork_admission_authority_state(conn)
        .map_err(pos_core::ForkAdmissionErrorV1::from)?
        .host
        .map(|host| host.store_id())
        .ok_or(pos_core::ForkAdmissionErrorV1::CorruptAuthority)
}

fn sqlite_decode_principal_owner_binding(
    record: (Vec<u8>, Vec<u8>, Vec<u8>),
) -> Result<PrincipalOwnerBindingV1, pos_core::ForkAdmissionErrorV1> {
    let (operation_id, principal_digest, bytes) = record;
    let binding = PrincipalOwnerBindingV1::from_canonical_cbor(&bytes)
        .map_err(|_| pos_core::ForkAdmissionErrorV1::CorruptAuthority)?;
    // A key column of the wrong width can never equal a 32-byte digest.
    if binding.input().operation_id.as_bytes().as_slice() != operation_id.as_slice()
        || binding.input().principal_digest.as_bytes().as_slice() != principal_digest.as_slice()
    {
        return Err(pos_core::ForkAdmissionErrorV1::CorruptAuthority);
    }
    Ok(binding)
}

fn with_fork_admission_recovery_transaction<T>(
    conn: &Connection,
    operation: impl FnOnce() -> Result<T, pos_core::ForkAdmissionErrorV1>,
) -> Result<T, pos_core::ForkAdmissionErrorV1> {
    // Recovery takes the writer reservation so its multi-row graph read cannot
    // interleave with a concurrent admission commit on another handle.
    conn.execute_batch("BEGIN IMMEDIATE")
        .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)?;
    match operation() {
        Ok(value) => conn
            .execute_batch("ROLLBACK")
            .map(|()| value)
            .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate),
        Err(error) => conn.execute_batch("ROLLBACK").map(|()| error).map_or(
            Err(pos_core::ForkAdmissionErrorV1::StorageIndeterminate),
            Err,
        ),
    }
}

fn sqlite_fork_admission_child_name(
    conn: &Connection,
    admission: &ForkAdmissionRecordV1,
) -> Result<Option<String>, pos_core::ForkAdmissionErrorV1> {
    let input = admission.input();
    conn.query_row(
        "SELECT name, parent_id, fork_seq FROM timelines WHERE id = ?1",
        params![input.child_timeline_id.to_string()],
        |row| {
            Ok((
                row.get::<_, Option<String>>(0)?,
                row.get::<_, Option<String>>(1)?,
                row.get::<_, Option<i64>>(2)?,
            ))
        },
    )
    .optional()
    .map_err(|_| pos_core::ForkAdmissionErrorV1::StorageIndeterminate)
    .map(|timeline| match timeline {
        Some((name, parent_id, fork_seq))
            if parent_id.as_deref() == Some(&input.parent_timeline_id.to_string())
                && fork_seq
                    .and_then(|seq| u64::try_from(seq).ok())
                    .is_some_and(|seq| seq == input.parent_logical_head) =>
        {
            name
        }
        _ => None,
    })
}

fn finish_fork_authority_transaction<T>(
    conn: &Connection,
    result: Result<T, ForkAdmissionAuthorityErrorV1>,
) -> Result<T, ForkAdmissionAuthorityErrorV1> {
    match result {
        Ok(value) => conn
            .execute_batch("COMMIT")
            .map(|()| value)
            .map_err(|_| ForkAdmissionAuthorityErrorV1::StorageIndeterminate),
        // A failed ROLLBACK leaves the outcome unknown; otherwise keep the cause.
        Err(error) => conn.execute_batch("ROLLBACK").map_or(
            Err(ForkAdmissionAuthorityErrorV1::StorageIndeterminate),
            |()| Err(error),
        ),
    }
}

fn with_fork_authority_transaction<T>(
    conn: &Connection,
    operation: impl FnOnce() -> Result<T, ForkAdmissionAuthorityErrorV1>,
) -> Result<T, ForkAdmissionAuthorityErrorV1> {
    conn.execute_batch("BEGIN IMMEDIATE")
        .map_err(|_| ForkAdmissionAuthorityErrorV1::StorageIndeterminate)?;
    finish_fork_authority_transaction(conn, operation())
}

impl AuthorityPersistencePortV1 for SqliteStore {
    fn bind_authority_persistence(
        &mut self,
        binding: AuthorityPersistenceBindingV1,
    ) -> Result<(), AuthorityPersistenceErrorV1> {
        match self.authority_persistence_binding {
            Some(bound) if bound != binding => Err(AuthorityPersistenceErrorV1::Unavailable),
            _ => {
                self.authority_persistence_binding = Some(binding);
                Ok(())
            }
        }
    }

    fn issue_capability_grant(
        &mut self,
        permit: AuthorityMutationPermitV1,
        grant: &CapabilityGrantV1,
    ) -> Result<AuthorityCommitOutcomeV1, AuthorityPersistenceErrorV1> {
        if self.authority_persistence_binding != Some(permit.persistence_binding()) {
            return Err(AuthorityPersistenceErrorV1::Unavailable);
        }
        self.conn
            .execute_batch("BEGIN IMMEDIATE")
            .map_err(|_| AuthorityPersistenceErrorV1::Unavailable)
            .and_then(|()| {
                let result = read_authority_state(&self.conn).and_then(|mut state| {
                    state
                        .issue_grant(permit, grant.clone())
                        .and_then(|outcome| {
                            write_authority_state(&self.conn, &state).map(|()| outcome)
                        })
                });
                finish_transaction(
                    &self.conn,
                    result,
                    |_, _| AuthorityPersistenceErrorV1::Unavailable,
                    |_, _| AuthorityPersistenceErrorV1::Unavailable,
                )
            })
    }

    fn revoke_capability_grant(
        &mut self,
        permit: AuthorityMutationPermitV1,
        revocation: &CapabilityRevocationV1,
    ) -> Result<AuthorityCommitOutcomeV1, AuthorityPersistenceErrorV1> {
        if self.authority_persistence_binding != Some(permit.persistence_binding()) {
            return Err(AuthorityPersistenceErrorV1::Unavailable);
        }
        self.conn
            .execute_batch("BEGIN IMMEDIATE")
            .map_err(|_| AuthorityPersistenceErrorV1::Unavailable)
            .and_then(|()| {
                let result = read_authority_state(&self.conn).and_then(|mut state| {
                    state
                        .revoke_grant(permit, revocation.clone())
                        .and_then(|outcome| {
                            write_authority_state(&self.conn, &state).map(|()| outcome)
                        })
                });
                finish_transaction(
                    &self.conn,
                    result,
                    |_, _| AuthorityPersistenceErrorV1::Unavailable,
                    |_, _| AuthorityPersistenceErrorV1::Unavailable,
                )
            })
    }

    fn load_authority(
        &self,
        leaf_grant_id: Hash,
    ) -> Result<PersistedAuthorityV1, AuthorityPersistenceErrorV1> {
        read_authority_state(&self.conn).and_then(|state| state.resolve(leaf_grant_id))
    }
}

fn sqlite_load_key_registry(conn: &Connection) -> Result<Option<KeyRegistryStateV1>, CoreError> {
    let state_cbor = match conn.query_row(
        "SELECT state_cbor FROM key_registry WHERE singleton = 1",
        [],
        |row| row.get::<_, Vec<u8>>(0),
    ) {
        Ok(bytes) => bytes,
        Err(rusqlite::Error::QueryReturnedNoRows) => return Ok(None),
        Err(error) => return Err(CoreError::Storage(error.to_string())),
    };
    ciborium::from_reader(state_cbor.as_slice())
        .map_err(|error| CoreError::Serialization(error.to_string()))
        .and_then(|registry: KeyRegistryStateV1| {
            registry
                .validate()
                .map(|()| registry)
                .map_err(|error| CoreError::Serialization(error.to_string()))
        })
        .map(Some)
}

struct SqliteRollbackOnDrop<'a>(&'a Connection);

impl Drop for SqliteRollbackOnDrop<'_> {
    fn drop(&mut self) {
        if !self.0.is_autocommit() {
            drop(self.0.execute_batch("ROLLBACK"));
        }
    }
}

fn finish_transaction<T, E>(
    conn: &Connection,
    result: Result<T, E>,
    commit_failure: impl FnOnce(rusqlite::Error, Option<rusqlite::Error>) -> E,
    rollback_failure: impl FnOnce(E, rusqlite::Error) -> E,
) -> Result<T, E> {
    match result {
        Ok(value) => match conn.execute_batch("COMMIT") {
            Ok(()) => Ok(value),
            Err(commit_error) => Err(commit_failure(
                commit_error,
                conn.execute_batch("ROLLBACK").err(),
            )),
        },
        Err(error) => match conn.execute_batch("ROLLBACK") {
            Ok(()) => Err(error),
            Err(rollback_error) => Err(rollback_failure(error, rollback_error)),
        },
    }
}

const fn mode_str(mode: TimelineMode) -> &'static str {
    match mode {
        TimelineMode::Historical => "historical",
        TimelineMode::Live => "live",
        TimelineMode::Future => "future",
    }
}

/// Persist a [`Seq`] as `SQLite` INTEGER (saturates at [`i64::MAX`]).
fn seq_as_i64(seq: Seq) -> i64 {
    i64::try_from(seq.as_u64()).unwrap_or(i64::MAX)
}

fn sqlite_fork_prefix(fork_seq: Option<i64>) -> Result<u64, CoreError> {
    fork_seq.map_or(Ok(0), |value| {
        u64::try_from(value)
            .map_err(|_| CoreError::Storage("invalid Fork prefix sequence".to_owned()))
    })
}

fn sqlite_origin_seq(inherited_prefix: u64, local_seq: Seq) -> Result<(u64, i64), CoreError> {
    let logical_seq = crate::checked_logical_head(inherited_prefix, local_seq.as_u64())?;
    let sql_seq = i64::try_from(logical_seq)
        .map_err(|_| CoreError::Storage("origin sequence exceeds SQLite range".to_owned()))?;
    Ok((logical_seq, sql_seq))
}

struct AppendContext {
    seq: Seq,
    chain_head: Hash,
    origin_logical_seq: u64,
    origin_sql_seq: i64,
}

fn read_append_context(
    tx: &Connection,
    timeline: TimelineId,
    missing_timeline: CoreError,
) -> Result<AppendContext, CoreError> {
    let head = tx.query_row(
        "SELECT head_seq, chain_head, fork_seq FROM timelines WHERE id = ?1",
        params![timeline.to_string()],
        |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, Vec<u8>>(1)?,
                row.get::<_, Option<i64>>(2)?,
            ))
        },
    );
    let (head_seq, chain_head, fork_seq) = match head {
        Ok(value) => value,
        Err(rusqlite::Error::QueryReturnedNoRows) => return Err(missing_timeline),
        Err(error) => return Err(CoreError::Storage(error.to_string())),
    };
    let chain_head: [u8; 32] = chain_head
        .try_into()
        .map_err(|_| CoreError::Serialization("bad hash length".to_owned()))?;
    let seq = Seq::from_u64(u64::try_from(head_seq).unwrap_or(0)).next();
    let inherited_prefix = sqlite_fork_prefix(fork_seq)?;
    let (origin_logical_seq, origin_sql_seq) = sqlite_origin_seq(inherited_prefix, seq)?;
    Ok(AppendContext {
        seq,
        chain_head: Hash::from_bytes(chain_head),
        origin_logical_seq,
        origin_sql_seq,
    })
}

fn read_origin_prefix(conn: &Connection, timeline: TimelineId) -> Result<u64, CoreError> {
    let fork_seq: Option<i64> = conn
        .query_row(
            "SELECT fork_seq FROM timelines WHERE id = ?1",
            params![timeline.to_string()],
            |row| row.get(0),
        )
        .map_err(|error| CoreError::Storage(error.to_string()))?;
    sqlite_fork_prefix(fork_seq)
}

fn ensure_read_time_bound(
    started: Option<Instant>,
    max_elapsed_micros: u64,
) -> Result<(), CoreError> {
    if let Some(started) = started {
        let elapsed_micros = u64::try_from(started.elapsed().as_micros()).unwrap_or(u64::MAX);
        if elapsed_micros > max_elapsed_micros {
            return Err(CoreError::ReadTimeTooLarge { elapsed_micros });
        }
    }
    Ok(())
}

fn decode_own_event(
    row: &rusqlite::Row<'_>,
    timeline: TimelineId,
    inherited_prefix: u64,
) -> Result<Event, CoreError> {
    let mut event = decode_event_row(row)?;
    crate::finalize_committed_origins(
        timeline,
        inherited_prefix,
        std::slice::from_mut(&mut event),
    )?;
    Ok(event)
}

/// Persist a `u64` micros value as `SQLite` INTEGER (saturates at [`i64::MAX`]).
fn u64_as_i64(v: u64) -> i64 {
    i64::try_from(v).unwrap_or(i64::MAX)
}

fn parse_mode(s: &str) -> TimelineMode {
    match s {
        "historical" => TimelineMode::Historical,
        "future" => TimelineMode::Future,
        _ => TimelineMode::Live,
    }
}

struct SqliteEventSecurityFields {
    signature_owner_id: Option<String>,
    signature_role: Option<i64>,
    signature_epoch: Option<i64>,
    origin_timeline_id: Option<String>,
    origin_logical_seq: Option<i64>,
}

fn sqlite_event_security_fields(event: &Event) -> Result<SqliteEventSecurityFields, CoreError> {
    let signature_epoch = event
        .signature_identity
        .map(|identity| {
            i64::try_from(identity.epoch).map_err(|_| {
                CoreError::Storage("signature key epoch exceeds SQLite INTEGER range".to_owned())
            })
        })
        .transpose()?;
    let origin_logical_seq = event
        .origin
        .map(|origin| {
            i64::try_from(origin.origin_logical_seq.as_u64())
                .map_err(|_| CoreError::Storage("origin sequence exceeds SQLite range".to_owned()))
        })
        .transpose()?;
    Ok(SqliteEventSecurityFields {
        signature_owner_id: event
            .signature_identity
            .map(|identity| identity.owner_id.as_str().to_owned()),
        signature_role: event
            .signature_identity
            .map(|identity| i64::from(identity.role.code())),
        signature_epoch,
        origin_timeline_id: event
            .origin
            .map(|origin| origin.origin_timeline_id.to_string()),
        origin_logical_seq,
    })
}

fn require_event_security_columns(columns: &HashSet<String>) -> Result<(), CoreError> {
    if !columns.contains("signature_owner_id")
        || !columns.contains("signature_role")
        || !columns.contains("signature_epoch")
    {
        return Err(CoreError::Storage(
            "SQLite events table is missing required signature identity columns".to_owned(),
        ));
    }
    if !columns.contains("origin_timeline_id") || !columns.contains("origin_logical_seq") {
        return Err(CoreError::Storage(
            "SQLite events table is missing required origin context columns".to_owned(),
        ));
    }
    Ok(())
}

fn decode_signature(bytes: Option<Vec<u8>>) -> Result<Option<pos_core::Signature>, CoreError> {
    bytes
        .map(|bytes| {
            bytes
                .try_into()
                .map(pos_core::Signature::from_bytes)
                .map_err(|_| CoreError::Serialization("bad signature length".to_owned()))
        })
        .transpose()
}

fn decode_event_security_context(
    row: &rusqlite::Row<'_>,
) -> Result<
    (
        Option<pos_core::Signature>,
        Option<KeyIdentityV1>,
        EventOriginV1,
    ),
    CoreError,
> {
    let signature_bytes: Option<Vec<u8>> = row
        .get(10)
        .map_err(|error| CoreError::Storage(error.to_string()))?;
    let owner_id: Option<String> = row
        .get(11)
        .map_err(|error| CoreError::Storage(error.to_string()))?;
    let role: Option<i64> = row
        .get(12)
        .map_err(|error| CoreError::Storage(error.to_string()))?;
    let epoch: Option<i64> = row
        .get(13)
        .map_err(|error| CoreError::Storage(error.to_string()))?;
    let origin_timeline_id: String = row
        .get(14)
        .map_err(|error| CoreError::Storage(error.to_string()))?;
    let origin_logical_seq: i64 = row
        .get(15)
        .map_err(|error| CoreError::Storage(error.to_string()))?;
    let origin_logical_seq = u64::try_from(origin_logical_seq)
        .ok()
        .filter(|seq| *seq >= 1)
        .ok_or_else(|| CoreError::Serialization("invalid Event origin sequence".to_owned()))?;
    Ok((
        decode_signature(signature_bytes)?,
        decode_signature_identity(owner_id, role, epoch)?,
        EventOriginV1 {
            origin_timeline_id: parse_timeline_id(&origin_timeline_id)?,
            origin_logical_seq: Seq::from_u64(origin_logical_seq),
        },
    ))
}

struct RawEventRow {
    seq: i64,
    event_id: String,
    entity_id: String,
    event_type: String,
    payload: Vec<u8>,
    wall_time: i64,
    causation_id: Option<String>,
    correlation_id: Option<String>,
    schema_version: i64,
}

fn read_event_row_fields(row: &rusqlite::Row<'_>) -> Result<RawEventRow, CoreError> {
    let storage_error = |error: rusqlite::Error| CoreError::Storage(error.to_string());
    Ok(RawEventRow {
        seq: row.get(0).map_err(storage_error)?,
        event_id: row.get(1).map_err(storage_error)?,
        entity_id: row.get(2).map_err(storage_error)?,
        event_type: row.get(3).map_err(storage_error)?,
        payload: row.get(4).map_err(storage_error)?,
        wall_time: row.get(5).map_err(storage_error)?,
        causation_id: row.get(6).map_err(storage_error)?,
        correlation_id: row.get(7).map_err(storage_error)?,
        schema_version: row.get(8).map_err(storage_error)?,
    })
}

fn decode_event_row(row: &rusqlite::Row<'_>) -> Result<Event, CoreError> {
    let RawEventRow {
        seq,
        event_id,
        entity_id,
        event_type,
        payload,
        wall_time,
        causation_id,
        correlation_id,
        schema_version,
    } = read_event_row_fields(row)?;
    if schema_version != i64::from(SchemaVersion::V1.as_u32()) {
        return Err(CoreError::Serialization(
            "unsupported event schema version".to_owned(),
        ));
    }
    let ph_bytes: Vec<u8> = row.get(9).map_err(|e| CoreError::Storage(e.to_string()))?;
    let ph_arr: [u8; 32] = ph_bytes
        .try_into()
        .map_err(|_| CoreError::Serialization("bad hash".to_owned()))?;
    let (signature, signature_identity, origin) = decode_event_security_context(row)?;
    let seq = u64::try_from(seq)
        .map_err(|_| CoreError::Serialization("bad event sequence".to_owned()))?;
    let wall_time = u64::try_from(wall_time)
        .map_err(|_| CoreError::Serialization("bad event wall time".to_owned()))?;
    let event = Event {
        id: parse_event_id(&event_id)?,
        entity: parse_entity_id(&entity_id)?,
        event_type: Kind::new(event_type),
        payload: CanonicalBytes::from_vec(payload),
        wall_time: WallTime::from_micros(wall_time),
        seq: Seq::from_u64(seq),
        causation_id: causation_id.as_deref().map(parse_event_id).transpose()?,
        correlation_id: correlation_id
            .as_deref()
            .map(parse_correlation_id)
            .transpose()?,
        schema_version: SchemaVersion::V1,
        signature,
        signature_identity,
        origin: Some(origin),
        payload_hash: pos_core::Hash::from_bytes(ph_arr),
    };
    pos_core::store::validate_event_signature(&event)?;
    Ok(event)
}

fn decode_signature_identity(
    owner_id: Option<String>,
    role: Option<i64>,
    epoch: Option<i64>,
) -> Result<Option<KeyIdentityV1>, CoreError> {
    match (owner_id, role, epoch) {
        (None, None, None) => Ok(None),
        (Some(owner_id), Some(role), Some(epoch)) => {
            let owner_id = OwnerIdV1::new(owner_id)
                .map_err(|_| CoreError::Serialization("bad signature owner".to_owned()))?;
            Ok(Some(KeyIdentityV1::new(
                owner_id,
                KeyRoleV1::from_code(
                    u8::try_from(role)
                        .map_err(|_| CoreError::Serialization("bad signature role".to_owned()))?,
                )
                .map_err(|_| CoreError::Serialization("bad signature role".to_owned()))?,
                u64::try_from(epoch)
                    .map_err(|_| CoreError::Serialization("bad signature epoch".to_owned()))?,
            )))
        }
        _ => Err(CoreError::Serialization(
            "signature identity is incomplete".to_owned(),
        )),
    }
}

fn parse_timeline_id(s: &str) -> Result<TimelineId, CoreError> {
    let ulid = s
        .parse::<ulid::Ulid>()
        .map_err(|_| CoreError::Serialization(format!("invalid ULID: {s}")))?;
    Ok(TimelineId::from_ulid(ulid))
}

fn parse_event_id(s: &str) -> Result<EventId, CoreError> {
    let ulid = s
        .parse::<ulid::Ulid>()
        .map_err(|_| CoreError::Serialization(format!("invalid ULID: {s}")))?;
    Ok(EventId::from_ulid(ulid))
}

fn parse_entity_id(s: &str) -> Result<EntityId, CoreError> {
    let ulid = s
        .parse::<ulid::Ulid>()
        .map_err(|_| CoreError::Serialization(format!("invalid ULID: {s}")))?;
    Ok(EntityId::from_ulid(ulid))
}

fn parse_correlation_id(s: &str) -> Result<pos_core::CorrelationId, CoreError> {
    let ulid = s
        .parse::<ulid::Ulid>()
        .map_err(|_| CoreError::Serialization(format!("invalid ULID: {s}")))?;
    Ok(pos_core::CorrelationId::from_ulid(ulid))
}

