    #[test]
    #[cfg_attr(coverage_nightly, coverage(off))]
    fn open_rejects_incompatible_erasure_persistence_schema() {
        for schema in [
            "CREATE TABLE erasure_records (request_digest BLOB PRIMARY KEY);",
            "CREATE TABLE erasure_evidence (reference_digest BLOB PRIMARY KEY);",
            "CREATE TABLE erasure_states (state_digest BLOB PRIMARY KEY);",
            "CREATE TABLE erasure_records (
                request_digest BLOB NOT NULL CHECK (length(request_digest) = 32),
                state_digest BLOB NOT NULL CHECK (length(state_digest) = 32),
                record_cbor BLOB NOT NULL CHECK (length(record_cbor) <= 67108864)
            );",
            "CREATE TABLE erasure_states (
                state_digest BLOB PRIMARY KEY CHECK (length(state_digest) = 32),
                request_digest BLOB NOT NULL CHECK (length(request_digest) = 32),
                state_cbor BLOB NOT NULL CHECK (length(state_cbor) <= 1048576)
            );",
        ] {
            let file = tempfile::NamedTempFile::new().test_ok();
            {
                let conn = Connection::open(file.path()).test_ok();
                conn.execute(schema, []).test_ok();
            }
            let error = SqliteStore::open(file.path().to_str().test_ok())
                .err()
                .test_ok();
            assert!(matches!(
                error,
                CoreError::Storage(message) if message.contains("schema")
            ));
        }
    }

    #[test]
    fn schema_validation_rejects_missing_erasure_and_authority_constraints() {
        let store = new_store();
        let records = ERASURE_SCHEMA_TABLES
            .iter()
            .find(|table| table.name == "erasure_records")
            .test_ok();
        let incompatible_records = SqliteSchemaTable {
            name: records.name,
            columns_query: records.columns_query,
            columns: records.columns,
            constraints: &["CHECK (length(request_digest) = 31)"],
        };
        let erasure_error = store
            .validate_sqlite_schema_table(&incompatible_records)
            .err()
            .test_ok();
        assert!(matches!(
            erasure_error,
            CoreError::Storage(message) if message.contains("erasure_records")
        ));

        store
            .conn
            .execute_batch(
                "DROP TABLE authority_state;
                 CREATE TABLE authority_state (
                     singleton INTEGER PRIMARY KEY,
                     schema_version INTEGER NOT NULL CHECK (schema_version = 1),
                     state_cbor BLOB NOT NULL
                 );",
            )
            .test_ok();
        assert!(matches!(
            store.validate_authority_schema(),
            Err(CoreError::Storage(message)) if message.contains("authority_state")
        ));
    }

    #[test]
    fn complete_inventory_rejects_truncating_durable_requests() {
        let mut store = new_store();
        for discriminator in [1_u8, 2] {
            store
                .conn
                .execute(
                    "INSERT INTO erasure_records
                     (request_digest, manifest_digest, manifest_cbor)
                     VALUES (?1, ?2, ?3)",
                    params![
                        [discriminator; 32].as_slice(),
                        [discriminator.saturating_add(10); 32].as_slice(),
                        [discriminator].as_slice(),
                    ],
                )
                .test_ok();
        }
        assert_eq!(
            store.complete_erasure_inventory_snapshot(1),
            Err(ErasureErrorV1::ScopeInvalid)
        );
    }

