    fn install_row_error_function(store: &SqliteStore) {
        store
            .conn
            .create_scalar_function(
                "row_error",
                0,
                rusqlite::functions::FunctionFlags::default(),
                |_context| {
                    Err::<String, _>(rusqlite::Error::UserFunctionError(Box::new(
                        std::io::Error::other("injected row error"),
                    )))
                },
            )
            .test_ok();
    }

