    #[derive(Clone, Copy)]
    enum CompetingMutation {
        Rotate,
        BeginDestruction,
    }

    #[test]
    fn historical_decryption_holds_registry_lock_through_callback() {
        for mutation in [
            CompetingMutation::Rotate,
            CompetingMutation::BeginDestruction,
        ] {
            check_historical_decryption_lock(mutation);
        }
    }

    fn check_historical_decryption_lock(mutation: CompetingMutation) {
        let old = KeyIdentityV1::new("subject-owner", KeyRoleV1::SubjectDataEncryption, 1);
        let current = KeyIdentityV1::new("subject-owner", KeyRoleV1::SubjectDataEncryption, 2);
        let database = tempfile::NamedTempFile::new().test_ok();
        let path = database.path().to_str().test_ok();
        let mut registry = KeyRegistryStateV1::new();
        registry
            .register_key(KeyRegistrationV1::new(old, Hash::from_bytes([1; 32]), None))
            .test_ok();
        let mut rotated = registry.clone();
        rotated
            .register_key(KeyRegistrationV1::new(
                current,
                Hash::from_bytes([2; 32]),
                None,
            ))
            .test_ok();
        let request =
            KeyDestructionRequestV1::new(old, Hash::from_bytes([1; 32]), Hash::from_bytes([3; 32]));
        let mut setup = open_store_at(path);
        setup.save_key_registry(&registry).test_ok();
        drop(setup);

        let mut decrypting_store = open_store_at(path);
        let mut mutating_store = open_store_at(path);
        mutating_store.conn.busy_timeout(Duration::ZERO).test_ok();
        let (entered_tx, entered_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let (mutation_tx, mutation_rx) = std::sync::mpsc::channel();
        let rotated_for_mutation = &rotated;
        let (decryption_result, mutation_result) = std::thread::scope(|scope| {
            let decryption = scope.spawn(move || {
                decrypting_store.with_decryption_authorization(
                    old,
                    Hash::from_bytes([1; 32]),
                    || {
                        entered_tx.send(()).test_ok();
                        release_rx.recv().test_ok();
                        "plaintext"
                    },
                )
            });
            let entered = entered_rx.recv_timeout(Duration::from_secs(5));
            if entered.is_err() {
                assert!(release_tx.send(()).is_ok(), "callback must be released");
            }
            assert!(
                entered.is_ok(),
                "decryption callback did not start: {entered:?}"
            );

            let mutation = scope.spawn(move || {
                let result = match mutation {
                    CompetingMutation::Rotate => {
                        mutating_store.save_key_registry(rotated_for_mutation)
                    }
                    CompetingMutation::BeginDestruction => mutating_store
                        .begin_key_registry_destruction(request)
                        .map(|_| ()),
                };
                mutation_tx.send(result).test_ok();
            });
            let mutation_result = mutation_rx.recv_timeout(Duration::from_secs(5));
            release_tx.send(()).test_ok();
            let decryption_result = decryption.join().test_ok();
            mutation.join().test_ok();
            (decryption_result, mutation_result)
        });
        assert_eq!(decryption_result, Ok("plaintext"));
        assert!(mutation_result
            .test_ok()
            .is_err_and(|error| error.to_string().contains("database is locked")));

        let mut verify = open_store_at(path);
        assert_eq!(verify.load_key_registry().test_ok(), Some(registry));
        match mutation {
            CompetingMutation::Rotate => {
                verify.save_key_registry(&rotated).test_ok();
                assert_eq!(
                    verify.with_decryption_authorization(old, Hash::from_bytes([1; 32]), || {
                        "old plaintext"
                    }),
                    Ok("old plaintext")
                );
            }
            CompetingMutation::BeginDestruction => {
                verify.begin_key_registry_destruction(request).test_ok();
                assert_eq!(
                    verify.with_decryption_authorization(old, Hash::from_bytes([1; 32]), || {}),
                    Err(KeyRegistryErrorV1::DestructionPending)
                );
            }
        }
    }

    #[test]
    fn signed_append_holds_registry_lock_until_commit_before_rotation() {
        let database = tempfile::NamedTempFile::new().test_ok();
        let path = database.path().to_str().test_ok();
        let identity = KeyIdentityV1::new("test-owner", KeyRoleV1::TimelineIntegritySigning, 1);
        let mut registry = KeyRegistryStateV1::new();
        registry
            .register_key(KeyRegistrationV1::new(
                identity,
                Hash::from_bytes([3; 32]),
                Some(pos_core::PublicKey::from_bytes([4; 32])),
            ))
            .test_ok();
        let mut rotated = registry.clone();
        rotated
            .register_key(KeyRegistrationV1::new(
                KeyIdentityV1::new(identity.owner_id, identity.role, 2),
                Hash::from_bytes([5; 32]),
                Some(pos_core::PublicKey::from_bytes([6; 32])),
            ))
            .test_ok();
        let mut setup = open_store_at(path);
        setup.save_key_registry(&registry).test_ok();
        let timeline_id = setup.create_timeline("registry-rotation").test_ok().id();
        let mut event = setup
            .append(timeline_id, &[make_draft(EntityId::new(), b"seed")])
            .test_ok()
            .into_iter()
            .next()
            .test_ok();
        event.id = EventId::new();
        event.origin = None;
        drop(setup);

        let mut signing_store = open_store_at(path);
        let mut rotation_store = open_store_at(path);
        rotation_store.conn.busy_timeout(Duration::ZERO).test_ok();
        let (entered_tx, entered_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let (rotation_result_tx, rotation_result_rx) = std::sync::mpsc::channel();
        let expected = registry.clone();
        let rotation_attempt = rotated.clone();

        let (sign_result, rotation_result) = std::thread::scope(|scope| {
            let sign_handle = scope.spawn(move || {
                let mut callback = move |_registry: &KeyRegistryStateV1, seq: Seq| {
                    entered_tx.send(()).test_ok();
                    release_rx.recv().test_ok();
                    event.seq = seq;
                    Ok::<Event, CoreError>(event.clone())
                };
                signing_store.append_signed_authorized(timeline_id, &expected, &mut callback)
            });
            let entered = entered_rx.recv_timeout(Duration::from_secs(5));
            if entered.is_err() {
                assert!(
                    release_tx.send(()).is_ok(),
                    "signing worker exited before callback: {entered:?}"
                );
            }
            assert!(
                entered.is_ok(),
                "signing callback did not enter its transaction: {entered:?}"
            );
            let rotation_handle = scope.spawn(move || {
                rotation_result_tx
                    .send(rotation_store.save_key_registry(&rotation_attempt))
                    .test_ok();
            });
            let rotation_result = rotation_result_rx.recv_timeout(Duration::from_secs(5));
            release_tx.send(()).test_ok();
            let sign_result = sign_handle.join().test_ok();
            rotation_handle.join().test_ok();
            (sign_result, rotation_result.test_ok())
        });

        sign_result.test_ok();
        assert!(
            rotation_result.is_err_and(|error| error.to_string().contains("database is locked"))
        );
        let mut verify = open_store_at(path);
        assert_eq!(verify.read(timeline_id, SeqRange::all()).test_ok().len(), 2);
        assert_eq!(verify.load_key_registry().test_ok(), Some(registry.clone()));
        verify.save_key_registry(&rotated).test_ok();
        let mut callback_called = false;
        let mut late_callback = |_registry: &KeyRegistryStateV1, _seq: Seq| {
            callback_called = true;
            Err::<Event, _>(CoreError::Storage("callback must not run".to_owned()))
        };
        assert!(verify
            .append_signed_authorized(timeline_id, &registry, &mut late_callback)
            .is_err());
        assert!(!callback_called);
    }

